import {originCinematics,originMemoryEarned} from './origin-cinema.js?v=5.18.0';
import {COMBAT_RELICS} from './combat-relics.js?v=5.16.0';
import {REACTION_RULES} from './combat-reactions.js?v=5.38';
import {RIVALS} from './npc-challenges.js?v=5.38';
import {SCHOOLS} from './constellation-model.js';
import {REGIONS as FRONTIER_REGIONS,SIDE_CAMPAIGNS} from './frontiers.js?v=5.41';
import {FRONTIER_BESTIARY} from './repertoire.js?v=5.38';
import {REGIONS} from './regional-content.js?v=5.16.0';
import {HOUSEHOLDS} from './townlife-content.js';
import {PHYSICAL_LORE} from './physical-lore-content.js';
import {RARE_MAKO,hasWayglass} from './wayglass-model.js?v=5.11.0';
import {CORES,CREW} from './mako.js?v=5.16.0';
const shot=(art,caption,focus=[.5,.45],zoom=1.04)=>({art,caption,focus,zoom});
export const STORY_ART={community:'living-world-cinderfall-v1.webp',instrument:'living-world-wayglass-v1.webp',combat:'living-world-concord-v1.webp'};
export function regionArt(chapter,frame=0){if(chapter<=8)return `chapter-${chapter}-${frame}.webp`;if([9,10,11].includes(chapter))return 'late-lowbank-v1.webp';if([12,13,14,17].includes(chapter))return 'late-glass-chamber-v1.webp';if([15,16,18,20,21,23].includes(chapter))return 'late-witness-court-v1.webp';return 'late-choir-storm-v1.webp';}
export const TACTICS=[['break','A moment to answer','An interrupted charge leaves the crew room to act.'],['link','More than one voice','A shared technique draws strength from the companions who join it.'],['echo','The answering pulse','The first pattern leaves room for a second.'],['field','A place that remembers','The pattern stays in the ground after its maker steps away.'],['counter','Hold, then answer','A prepared response turns defence into opportunity.'],['leech','A measured return','Part of the force spent returns to its maker.'],['rare','What the crystal changes','A recovered mineral pattern gives a familiar technique a different consequence.'],['overdrive','The cost of brilliance','Great force asks something of the body that carries it.']];
export function expansionCinematics(){const entries=[];const add=e=>entries.push({expansion:true,environment:true,kind:'living-world',duration:6.8,color:'#c6d8bd',priority:4,...e});
for(const p of REGIONS){const art=regionArt(p.chapter);const common={chapter:p.chapter,regionScene:p.scene,color:p.color};
add({...common,id:'world:region:'+p.chapter,topic:'region',key:p.chapter,title:p.name,subtitle:p.custom,musicId:'town',duration:6,shots:[shot(art,'A place is more than the road through it.',[.35,.4],1.02),shot(art,p.custom,[.65,.48],1.18)]});
add({...common,id:'world:project:'+p.chapter,topic:'project',key:p.chapter,title:'Work that remains',subtitle:p.craft,priority:2,musicId:'victory',shots:[shot(art,'The '+p.craft+' has a purpose again.',[.45,.5],1.12),shot(art,p.custom,[.65,.42],1.04)]});
add({...common,id:'world:botany:'+p.chapter,topic:'botany',key:p.chapter,title:p.plant,subtitle:'A small cutting. The roots stay.',compact:true,duration:2.4,shots:[shot(art,'A small cutting. The roots stay.',[.45,.65],1.2)]});
add({...common,id:'world:wildlife:'+p.chapter,topic:'wildlife',key:p.chapter,title:'Life between journeys',subtitle:'The '+p.fauna+' goes on with its day.',compact:true,duration:2.4,shots:[shot(art,'You make room for a smaller rhythm.',[.4,.5],1.08)]});
add({...common,id:'world:study:'+p.chapter,topic:'study',key:p.chapter,title:'Learned by listening',subtitle:p.name+' · a local pattern',musicId:'workshop',priority:3,shots:[shot(art,'Work has a rhythm before it has a name.',[.4,.45],1.03),shot(STORY_ART.instrument,'You carry the pattern as understanding, not possession.',[.44,.52],1.12)]});}
for(const f of HOUSEHOLDS)add({id:'world:household:'+f.id,topic:'household',key:f.id,chapter:f.chapter,title:'Someone remembered',subtitle:f.family+' household · '+f.town,musicId:'home',priority:2,shots:[shot(f.id==='vale'?STORY_ART.community:regionArt(f.chapter),f.parcel[0].toUpperCase()+f.parcel.slice(1)+' reaches '+f.names[1]+'.',[.6,.5],1.1),shot(f.id==='vale'?STORY_ART.community:regionArt(f.chapter),f.care,[.45,.45],1.04)]});
for(const a of PHYSICAL_LORE)add({id:'world:object:'+a.id,topic:'physical',key:a.id,chapter:a.chapter,title:a.name,subtitle:a.device,priority:1,color:a.color,musicId:'discovery',motif:a.mode,shots:[shot(regionArt(a.chapter),a.meaning,[.42,.45],1.04),shot(STORY_ART.instrument,'The '+a.device+' responds to what you changed.',[.7,.57],1.16),shot(regionArt(a.chapter,2),'The place keeps the change after you leave.',[.6,.5],1.04)]});
for(const r of RARE_MAKO)add({id:'world:rare:'+r.id,topic:'rare',key:r.id,chapter:r.chapter,title:r.name,subtitle:r.effect,priority:0,musicId:'discovery',color:r.color,motif:'mineral',duration:8.5,shots:[shot(regionArt(r.chapter),'The signal led to a seam. The crystal was still yours to find.',[.45,.5],1.03),shot(STORY_ART.instrument,r.lore.split('. ')[0]+'.',[.36,.52],1.2),shot(STORY_ART.instrument,r.effect,[.7,.45],1.08)]});
add({id:'world:wayglass',topic:'wayglass',title:'An observatory for the road',priority:0,chapter:1,musicId:'workshop',duration:8,shots:[shot(STORY_ART.instrument,'A folding brass lens. A mineral pulse. Nothing taken from another voice.',[.35,.52],1.12),shot(STORY_ART.instrument,'Calibrate the Wayglass, follow the signal, then recover the crystal itself.',[.67,.4],1.04),shot(STORY_ART.instrument,'The Resonance Paths teach its pattern. Crystal craft lets you carry it into battle.',[.5,.62],1.12)]});
for(const h of CREW)for(const threshold of [8,24,48])add({id:'world:growth:'+h.name+':'+threshold,topic:'growth',key:CREW.indexOf(h),threshold,title:h.name+' · a path of their own',subtitle:threshold+' patterns learned',musicId:'cinema_reveal',duration:5.5,priority:3,shots:[shot(STORY_ART.instrument,'A pattern becomes a choice. A choice becomes a habit.',[.37,.51],1.14),shot(STORY_ART.combat,'What '+h.name+' has learned can now change the way the crew answers.',[.45,.45],1.04)]});
for(const core of CORES)add({id:'world:core:'+core.id,topic:'core',key:core.id,title:core.name+' · a new pattern',subtitle:'Found in the world. Learned through practice.',musicId:'discovery',priority:1,color:core.color,motif:'mineral',duration:5.5,shots:[shot(STORY_ART.instrument,'A mineral pattern, carrying no captive voice.',[.36,.53],1.15),shot(STORY_ART.instrument,'Equip '+core.name+' in Crystal craft. Practice gives its pattern more range.',[.7,.46],1.04)]});
for(const region of FRONTIER_REGIONS){const index=FRONTIER_REGIONS.indexOf(region),art='frontier-'+region.id+'-v1.webp';for(let area=0;area<5;area++){const place=['Trailhead','Crossing','Hollow','Heights','Sanctuary'][area],scene=2000+index*5+area;add({id:'world:frontier-area:'+scene,topic:'frontier-area',key:scene,chapter:region.chapter,regionScene:scene,title:region.name+' · '+place,subtitle:region.description,color:region.color,priority:3,musicId:['salt','coral','mangrove'].includes(region.id)?'water_cavern':['crystal','aurora'].includes(region.id)?'archive':'explore',duration:6,shots:[shot(art,region.description,[.5,.44],1.02),shot(art,region.rule,[.35+area*.075,.52],1.12)]});}}
for(const campaign of SIDE_CAMPAIGNS){const region=FRONTIER_REGIONS[campaign.regionIndex],art='frontier-'+region.id+'-v1.webp';add({id:'world:commission:'+campaign.id,topic:'commission',key:campaign.id,chapter:campaign.chapter,title:campaign.title,subtitle:campaign.outcome,priority:2,color:region.color,musicId:'victory',duration:6.5,shots:[shot(art,campaign.patron+' · '+campaign.outcome,[.38,.5],1.12),shot(art,'The next travellers inherit a safer place.',[.62,.44],1.03)]});}
for(const species of FRONTIER_BESTIARY){const region=FRONTIER_REGIONS.find(r=>species.habitat?.includes(r.name))||FRONTIER_REGIONS[0],art='frontier-'+region.id+'-v1.webp';const common={chapter:species.chapter,regionScene:null,title:species.name,subtitle:species.tell,species:species.id,atlas:species.atlas,sprite:species.sprite,hue:species.hue||0,color:region.color,frontierPortrait:true,shots:[shot(art,species.tell,[.48,.42],1.03)]};add({...common,id:'creature:'+species.id,kind:'creature',topic:'frontier-creature',key:species.id,duration:3.5,priority:1,musicId:'danger'});add({...common,id:'creature-move:'+species.id,kind:'creature-move',topic:'frontier-move',key:species.id,subtitle:species.move,compact:true,duration:2,shots:[shot(art,species.move,[.48,.42],1.03)]});}
for(const threshold of [8,24,72,144])add({id:'world:rooms:'+threshold,topic:'rooms',threshold,title:'A room has a life',subtitle:'Objects tell you who belongs here.',priority:4,musicId:'home',duration:5.5,shots:[shot(STORY_ART.community,'A repaired hinge. A well-used cup. A plant turned toward the light.',[.66,.47],1.11),shot(STORY_ART.instrument,'You have learned to notice what a place is trying to tell you.',[.5,.55],1.04)]});
const schoolArt={kiln:'frontier-caldera-v1.webp',winter:'frontier-glacier-v1.webp',river:'frontier-mangrove-v1.webp',storm:'frontier-storm-v1.webp',wind:'frontier-aurora-v1.webp',night:'frontier-spore-v1.webp',stone:'frontier-marble-v1.webp',mercy:STORY_ART.community,haven:STORY_ART.community,orbit:'frontier-crystal-v1.webp',choir:STORY_ART.instrument,road:'frontier-dunes-v1.webp'};
for(const school of SCHOOLS){const art=schoolArt[school.id]||STORY_ART.instrument;add({id:'world:school:'+school.id,topic:'school',key:school.id,title:school.name,subtitle:school.realm,priority:2,color:school.color,musicId:'cinema_reveal',duration:6.5,shots:[shot(art,school.lore,[.46,.47],1.04),shot(STORY_ART.instrument,'Learning opens a possibility. Equip the school to shape matching recipes.',[.39,.52],1.12)]});add({id:'world:school-cap:'+school.id,topic:'school-cap',key:school.id,title:school.name+' · a chosen horizon',subtitle:'One path becomes your own.',priority:2,color:school.color,musicId:'discovery',duration:5.8,shots:[shot(art,school.lore,[.58,.44],1.12),shot(STORY_ART.combat,'Your chosen branch changes the way you answer. Another journey may choose differently.',[.44,.48],1.04)]});add({id:'world:school-cast:'+school.id,topic:'school-cast',key:school.id,title:school.name+' · put into practice',subtitle:school.condition,compact:true,duration:2.5,color:school.color,shots:[shot(art,'A learned pattern becomes an equipped, matching action.',[.5,.45],1.06)]});}
for(const relic of COMBAT_RELICS)add({id:'world:battle-relic:'+relic.id,topic:'battle-relic',key:relic.id,chapter:relic.chapter,title:relic.name,subtitle:relic.effect,priority:0,color:relic.color,musicId:'discovery',duration:7,shots:[shot(STORY_ART.instrument,relic.lore,[.37,.52],1.15),shot(STORY_ART.combat,relic.effect,[.6,.46],1.04)]});
for(const reaction of REACTION_RULES)add({id:'world:reaction:'+reaction.id,topic:'reaction',key:reaction.id,title:reaction.name,subtitle:reaction.effect,compact:true,duration:2.6,color:'#badde1',shots:[shot(STORY_ART.combat,reaction.trigger+' · '+reaction.effect,[.54,.44],1.05)]});
for(const rival of RIVALS)add({id:'world:rival:'+rival.id,topic:'rival',key:rival.id,chapter:rival.chapter,title:rival.name+' · a lesson earned',subtitle:rival.title,priority:1,musicId:'victory',duration:6,shots:[shot(regionArt(rival.chapter),'Respect is learned on both sides of a friendly challenge.',[.42,.45],1.04),shot(STORY_ART.combat,rival.gear.name+' is yours to carry into the next encounter.',[.58,.47],1.12)]});
for(const [id,title,subtitle]of TACTICS)add({id:'world:tactic:'+id,topic:'tactic',key:id,title,subtitle,compact:true,duration:2.6,color:'#c2dfe1',shots:[shot(STORY_ART.combat,subtitle,[.5,.45],1.05)]});return [...entries,...originCinematics(regionArt)];}
export function expansionEarned(e,s){if(!e.expansion)return false;if(e.topic?.startsWith('origin-'))return originMemoryEarned(e,s);const r=s.regionalLife||{};switch(e.topic){case'battle-relic':return(s.combatRelics?.owned||[]).includes(e.key);case'reaction':return(s.cinemaReactions||[]).includes(e.key);case'rival':return(s.rivals?.won||[]).includes(e.key);case'school':return(s.recruited||[]).some(id=>(s.skillGrid?.[id]||[]).includes('discipline:'+e.key+':root'));case'school-cap':return(s.recruited||[]).some(id=>(s.skillGrid?.[id]||[]).some(n=>n==='discipline:'+e.key+':cap'||n==='discipline:'+e.key+':memory'));case'school-cast':return(s.cinemaDoctrines||[]).includes(e.key);case'frontier-area':return(s.frontiers?.visited||[]).includes(e.key);case'commission':return(s.frontiers?.claimed||[]).includes(e.key);case'frontier-creature':return(s.cinemaEncounters||[]).includes(e.key);case'frontier-move':return(s.cinemaSeen||[]).includes(e.id);case'rooms':return(s.household?.examined||[]).length>=e.threshold;case'region':return (r.visited||[]).includes(e.key);case'project':return(r.projects||[]).includes(e.key);case'botany':return(r.botany||[]).includes(e.key);case'wildlife':return !!r.studies?.['wild:'+e.key];case'study':return !!r.studies?.['core:'+e.key];case'household':return(s.townLife?.delivered||[]).includes(e.key);case'physical':return(s.physicalLore?.completed||[]).includes(e.key);case'rare':return(s.kakeya?.relics||[]).includes(e.key);case'wayglass':return hasWayglass(s);case'growth':return(s.recruited||[]).includes(e.key)&&(s.skillGrid?.[e.key]||[]).length>=e.threshold;case'core':return(s.cores||[]).includes(e.key);case'tactic':return(s.cinemaTactics||[]).includes(e.key);default:return false;}}
export function tacticKeys(event){if(event.type==='interrupt')return['break'];if(!['cast','counter-ready'].includes(event.type))return[];const t=event.tech||{};return [t.link&&'link',t.echo&&'echo',t.field&&'field',t.counter&&'counter',t.leech&&'leech',(t.makoId||t.rareMako)&&'rare',t.overdrive&&'overdrive'].filter(Boolean);}
